// Types and helpers for the ID3 mushroom tree in model.json.
// model.json is generated by scripts/id3-mushrooms/train.mjs — don't hand-edit it.

export type Label = 'e' | 'p';

export interface Leaf {
  /** Verdict: edible or poisonous. */
  l: Label;
  /** Training specimens that reach this leaf. */
  n: number;
}

export interface Split {
  /** Index into `attributes`. */
  a: number;
  n: number;
  /** Information gain of this split, in bits. */
  g: number;
  /** Majority label, used for a value the tree never saw at this node. */
  d: Label;
  /** Child per attribute value code, largest first. */
  b: Record<string, TreeNode>;
}

export type TreeNode = Leaf | Split;

export interface Attribute {
  name: string;
  /** Value code → human-readable value. */
  values: Record<string, string>;
}

export interface Model {
  source: string;
  trainedOn: number;
  trainingErrors: number;
  attributes: Attribute[];
  tree: TreeNode;
  /** Label char followed by one value code per attribute. */
  specimens: string[];
}

export interface Step {
  /** Attribute tested at this node. */
  attr: number;
  /** Value the specimen has for it. */
  value: string;
  /** Path id of the node reached by following this value ("n/w/d"). */
  id: string;
}

export const isLeaf = (node: TreeNode): node is Leaf => 'l' in node;

export const pathId = (codes: string[]) => codes.join('/');

/** Walk the tree for one specimen; returns the steps taken and the verdict. */
export function classify(tree: TreeNode, x: string[]): { steps: Step[]; verdict: Label } {
  const steps: Step[] = [];
  const codes: string[] = [];
  let node: TreeNode | undefined = tree;
  while (node && !isLeaf(node)) {
    const split: Split = node;
    const value: string = x[split.a];
    const next: TreeNode | undefined = split.b[value];
    codes.push(value);
    steps.push({ attr: split.a, value, id: pathId(codes) });
    if (!next) return { steps, verdict: split.d };
    node = next;
  }
  return { steps, verdict: (node as Leaf).l };
}

export const labelName = (l: Label) => (l === 'p' ? 'poisonous' : 'edible');
